class Counter
{
    private int n = 0;
    public void Add()
    {
        n++;
    }
    public int Get()
    {
        return n;
    }
}
public class Program
{
    static void Main()
    {
        Tr.Begin();
        Counter a = new Counter();
        Tr.S("new ينشئ كائنًا، وa يشير إليه.", "a", a);
        Counter b = a;
        Tr.S("لا new: b يشير إلى الكائن نفسه.", "b", b);
        Counter c = new Counter();
        Tr.S("new ثانية: كائن ثانٍ مستقل.", "c", c);
        b.Add();
        Tr.S("b.Add() تزيد n في الكائن الأول.");
        b.Add();
        Tr.S("مرة ثانية: الكائن الأول n = 2.");
        c.Add();
        Tr.S("c.Add() تزيد الكائن الثاني.");
        Console.WriteLine(a.Get() + " " + b.Get() + " " + c.Get());
        Tr.S("الطباعة: 2 2 1.");
        Tr.End();
    }
}
